import React, { useEffect, useState } from 'react';
import AdminNav from '../../Components/AdminNav';

const emptyAd = { title: '', content: '', link: '', poster: '' };

export default function AdvertisementAdmin() {
  const [ads, setAds] = useState([]);
  const [formAd, setFormAd] = useState(emptyAd);
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState('');

  const fetchAds = async () => {
    try {
      const res = await fetch('http://localhost:5000/advertisements');
      if (res.ok) {
        const data = await res.json();
        setAds(data);
      } else {
        const err = await res.text();
        setMessage('Fetch ads failed: ' + err);
      }
    } catch (error) {
      setMessage('Failed to fetch ads: ' + error.message);
    }
  };

  useEffect(() => {
    fetchAds();
  }, []);

  const resetForm = () => {
    setFormAd(emptyAd);
    setEditingId(null);
    setMessage('');
  };

  const handleChange = e => {
    setFormAd({ ...formAd, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    if (!formAd.title || !formAd.content || !formAd.poster) {
      setMessage('Title, content, and poster URL are required');
      return;
    }
    try {
      let res;
      if (editingId) {
        res = await fetch(`http://localhost:5000/advertisements/${encodeURIComponent(editingId)}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formAd),
        });
      } else {
        res = await fetch('http://localhost:5000/advertisements', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formAd),
        });
      }

      if (res.ok) {
        setMessage(editingId ? 'Advertisement updated' : 'Advertisement added');
        resetForm();
        fetchAds();
      } else {
        const errorText = await res.text();
        setMessage('Failed to save: ' + errorText);
      }
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  const handleDelete = async id => {
    if (!window.confirm('Are you sure you want to delete this advertisement?')) return;
    try {
      const res = await fetch(`http://localhost:5000/advertisements/${encodeURIComponent(id)}`, {
        method: 'DELETE',
      });
      if (res.ok) {
        setMessage('Advertisement deleted');
        if (editingId === id) resetForm();
        fetchAds();
      } else {
        const errorText = await res.text();
        setMessage('Failed to delete advertisement: ' + errorText);
      }
    } catch (error) {
      setMessage('Error: ' + error.message);
    }
  };

  const startEdit = ad => {
    setFormAd({
      title: ad.title,
      content: ad.content,
      link: ad.link || '',
      poster: ad.poster,
    });
    setEditingId(ad.id);
    setMessage('');
  };

  return (
    <>
      <AdminNav />
      <div className="admin-container">
        <h2>{editingId ? 'Edit Advertisement' : 'Add Advertisement'}</h2>
        {message && <p className="message">{message}</p>}
        <form onSubmit={handleSubmit} className="ad-form">
          <label>Title</label>
          <input type="text" name="title" value={formAd.title} onChange={handleChange} required />

          <label>Description</label>
          <textarea name="content" value={formAd.content} onChange={handleChange} required rows="4" />

          <label>Poster URL</label>
          <input type="url" name="poster" value={formAd.poster} onChange={handleChange} required placeholder="https://..." />

          <label>Link (optional)</label>
          <input type="url" name="link" value={formAd.link} onChange={handleChange} placeholder="https://..." />

          <div className="buttons">
            <button type="submit">{editingId ? 'Update' : 'Add'}</button>
            {editingId && (
              <button type="button" onClick={resetForm} className="cancel-btn">
                Cancel
              </button>
            )}
          </div>
        </form>

        <h3>Existing Advertisements</h3>
        {ads.length === 0 && <p>No advertisements added yet.</p>}
        <ul className="ads-list">
          {ads.map(ad => (
            <li key={ad.id} className="ads-list-item">
              <div className="ads-info">
                <strong>{ad.title}</strong> - {ad.content.substring(0, 40)}...
              </div>
              <div className="ads-actions">
                <button onClick={() => startEdit(ad)}>Edit</button>
                <button onClick={() => handleDelete(ad.id)} className="delete-btn" style={{ marginLeft: 5, color: 'red' }}>
                  Delete
                </button>
              </div>
            </li>
          ))}
        </ul>
      </div>

      <style>{`
        .admin-container {
          max-width: 700px;
          margin: 20px auto;
          padding: 20px;
          background: #ffffff;
          border-radius: 8px;
          box-shadow: 0 4px 12px rgb(0 0 0 / 0.1);
          font-family: Arial, sans-serif;
        }
        .message {
          padding: 10px;
          background-color: #fffae6;
          color: #7a5901;
          border: 1px solid #ffd324;
          border-radius: 4px;
          margin-bottom: 15px;
        }
        label {
          display: block;
          margin-top: 15px;
          font-weight: 600;
        }
        input[type="text"], input[type="url"], textarea {
          width: 100%;
          padding: 10px;
          margin-top: 6px;
          border: 1px solid #ccc;
          border-radius: 4px;
          font-size: 14px;
          font-family: inherit;
          box-sizing: border-box;
        }
        textarea {
          resize: vertical;
        }
        .buttons {
          margin-top: 20px;
        }
        button {
          background-color: #007bff;
          color: white;
          font-weight: 600;
          padding: 10px 18px;
          border: none;
          border-radius: 4px;
          cursor: pointer;
          font-size: 15px;
          transition: background-color 0.2s ease;
        }
        button:hover {
          background-color: #0056b3;
        }
        .cancel-btn {
          background-color: #6c757d;
          margin-left: 10px;
        }
        .cancel-btn:hover {
          background-color: #565e64;
        }
        .ads-list {
          margin-top: 30px;
          list-style: none;
          padding: 0;
        }
        .ads-list-item {
          display: flex;
          justify-content: space-between;
          align-items: center;
          border: 1px solid #ddd;
          border-radius: 5px;
          padding: 12px 16px;
          margin-bottom: 10px;
          background-color: #fafafa;
        }
        .ads-info {
          flex-grow: 1;
          margin-right: 20px;
          font-size: 16px;
        }
        .ads-actions button {
          margin-left: 10px;
          padding: 6px 12px;
          font-size: 14px;
          border-radius: 4px;
        }
        .ads-actions .delete-btn {
          background-color: #dc3545;
          color: #fff;
          border: none;
          cursor: pointer;
        }
        .ads-actions .delete-btn:hover {
          background-color: #bd2130;
        }
      `}</style>
    </>
  );
}
